// Get the lead submitted from the website.
const lead = $json.body;

// Start the intent score.
let intentScore = 0;

// A dataset download is our strongest current conversion signal.
if (lead.conversion === 'dataset_download') {
  intentScore += 40;
}

// Start the fit score.
let fitScore = 0;

const fitReasons = [];

// Give points when the visitor provides an organization.
if (lead.organization && lead.organization.trim() !== '') {
  fitScore += 20;
  fitReasons.push('Organization provided');
}

// Check whether the organization appears to be in a relevant sector.
const organization = (lead.organization || '').toLowerCase();

const targetKeywords = [
  'mining',
  'minerals',
  'energy',
  'battery',
  'research',
  'university',
  'government'
];

const matchesTargetSector = targetKeywords.some(
  keyword => organization.includes(keyword)
);

if (matchesTargetSector) {
  fitScore += 30;
  fitReasons.push('Organization matches a target sector');
}

// Give a small signal for a professional email domain.
const email = (lead.email || '').toLowerCase();

const freeEmailDomains = [
  'gmail.com',
  'yahoo.com',
  'hotmail.com',
  'outlook.com'
];

const emailDomain = email.includes('@')
  ? email.split('@')[1]
  : '';

if (
  emailDomain &&
  !freeEmailDomains.includes(emailDomain)
) {
  fitScore += 10;
  fitReasons.push('Professional email domain');
}

// Keep the final score between 0 and 100.
const totalScore = Math.min(
  intentScore + fitScore,
  100
);

// Convert the score into a simple priority.
let priority = 'LOW';

if (totalScore >= 70) {
  priority = 'HIGH';
} else if (totalScore >= 40) {
  priority = 'MEDIUM';
}

// Return the original lead plus the scoring results.
return [
  {
    json: {
      ...lead,
      intent_score: intentScore,
      fit_score: fitScore,
      total_score: totalScore,
      priority: priority,
      fit_reasons: fitReasons
    }
  }
];

